// class key → [family, talent profile]
export const TOP_AFK_CLASS_PROFILE: Readonly<Record<string, readonly [string, string]>> = {"Beginner":["beginner","t79"],"Journeyman":["beginner","t79"],"Maestro":["beginner","t79"],"Voidwalker":["beginner","t79"],"Warrior":["warrior","t88"],"Barbarian":["warrior","t88"],"Blood_Berserker":["warrior","t88"],"Death_Bringer":["warrior","t88"],"Squire":["warrior","t88"],"Divine_Knight":["warrior","t88"],"Archer":["archer","t268"],"Bowman":["archer","t268"],"Siege_Breaker":["archer","t268"],"Hunter":["archer","t268"],"Beast_Master":["archer","t268"],"Wind_Walker":["archer","t268"],"Mage":["mage","t448"],"Shaman":["mage","t448"],"Bubonic_Conjuror":["mage","t448"],"Arcane_Cultist":["mage","t448"],"Wizard":["mage","t448"],"Elemental_Sorcerer":["mage","t448"],"Royal_Guardian":["warrior","t88"]};

// Family used when no class is known (the highest-reaching one).
export const TOP_AFK_DEFAULT_FAMILY = "beginner";

/** The top AFK Gains Rate reference for a class — its family's base merged with its profile. */
export function topAfkFlatForClass(classKey: string | null | undefined): FlatMap {
  const [family, profile] = (classKey && TOP_AFK_CLASS_PROFILE[classKey]) || [TOP_AFK_DEFAULT_FAMILY, "base"];
  const base = TOP_AFK_FAMILY_FLAT[family] ?? TOP_AFK_FAMILY_FLAT[TOP_AFK_DEFAULT_FAMILY];
  const override = TOP_AFK_PROFILE_OVERRIDES[`${family}:${profile}`];
  return override ? { ...base, ...override } : base;
}
